def from_roman(s):
    roman_numerals = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }
    total = 0
    prev_value = 0
    for char in reversed(s):
        value = roman_numerals[char]
        if value < prev_value:
            total -= value
        else:
            total += value
        prev_value = value
    return total

def test_round_trip():
    for i in range(1, 4000):
        assert from_roman(to_roman(i)) == i

if __name__ == "__main__":
    test_round_trip()
    print("All tests passed!")

